/**
 * agent-browser-viewer — browser half.
 *
 * Registers one right-Sidebar tab type ("Agent 浏览器") whose body polls
 * `/agent-browser-view/state` and renders the newest screenshot the host route
 * serves, so a person can watch what the agent's headless browser is showing.
 */
window.__ModuleLoader__.load({
  id: '@local/agent-browser-viewer',
  factory(require) {
    const React = require('react');
    const h = React.createElement;

    /** This package's tab-type id; also the keyed seat the body registers under. */
    const ID = '@local/agent-browser-viewer';
    /** The tab kind recorded in the Session's sidebar state. */
    const KIND = 'agent-browser-view';
    /** This package's copy namespace. */
    const NS = 'agentBrowserViewer';
    /** Host routes owned by this bundle's Host half. */
    const STATE_PATH = '/agent-browser-view/state';
    const IMAGE_PATH = '/agent-browser-view/latest.png';
    /** How often the body re-reads the host's screenshot metadata. */
    const POLL_MS = 2000;
    /** Age under which the view counts as live. */
    const FRESH_MS = 20000;

    /** Simplified Chinese dictionary and key-set source of truth. */
    const zh = {
      'type.label': 'Agent 浏览器',
      'guide.title': 'Agent 浏览器',
      'guide.description': '实时看 agent 无头浏览器的最新截图',
      'state.loading': '正在读取…',
      'state.empty.title': '还没有截图',
      'state.empty.body': 'Agent 打开浏览器并截图后，这里会自动显示最新一张。',
      'state.error': '读取失败',
      'state.live': '实时',
      'state.stale': '已停止',
      'state.dir': '目录',
      'state.updated': '更新于',
      ago: ' 秒前',
    };
    /** English dictionary, same key set. */
    const en = {
      'type.label': 'Agent browser',
      'guide.title': 'Agent browser',
      'guide.description': "Live view of the agent's headless browser screenshots",
      'state.loading': 'Reading…',
      'state.empty.title': 'No screenshot yet',
      'state.empty.body': "The newest screenshot shows up here once the agent opens its browser and captures one.",
      'state.error': 'Read failed',
      'state.live': 'live',
      'state.stale': 'idle',
      'state.dir': 'Directory',
      'state.updated': 'Updated',
      ago: 's ago',
    };

    /** One small key/value line under the image. */
    function Caption({ label, value, title }) {
      return h('div', { style: { display: 'flex', gap: '6px', minWidth: 0 } }, [
        h('span', { key: 'label', style: { color: 'var(--dsw-alias-label-caption)', flex: 'none' } }, label),
        h('span', {
          key: 'value',
          title,
          style: {
            color: 'var(--dsw-alias-label-secondary)',
            overflow: 'hidden',
            textOverflow: 'ellipsis',
            whiteSpace: 'nowrap',
            direction: 'rtl',
            textAlign: 'left',
          },
        }, value),
      ]);
    }

    /**
     * The tab body: the newest screenshot, its age, and where it came from.
     * @param props - slot props; `t` is the namespace-bound translate.
     */
    function Viewer(props) {
      const t = typeof props.t === 'function' ? props.t : (key) => zh[key] ?? key;
      const [state, setState] = React.useState({ phase: 'loading' });
      const [now, setNow] = React.useState(() => Date.now());

      React.useEffect(() => {
        let live = true;
        const read = async () => {
          try {
            const response = await fetch(STATE_PATH, { cache: 'no-store' });
            if (!response.ok) throw new Error(`HTTP ${String(response.status)}`);
            const data = await response.json();
            if (live) setState({ phase: 'ready', data });
          } catch (cause) {
            if (live) setState({ phase: 'error', message: cause instanceof Error ? cause.message : String(cause) });
          }
        };
        void read();
        const poll = setInterval(() => { void read(); }, POLL_MS);
        const clock = setInterval(() => { setNow(Date.now()); }, 1000);
        return () => {
          live = false;
          clearInterval(poll);
          clearInterval(clock);
        };
      }, []);

      const frame = {
        border: '1px solid var(--dsw-alias-border-l1)',
        borderRadius: '8px',
        background: 'var(--dsw-alias-bg-layer-1)',
        overflow: 'auto',
        flex: '1',
        minHeight: '120px',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
      };
      const root = {
        height: '100%',
        boxSizing: 'border-box',
        padding: '10px',
        display: 'flex',
        flexDirection: 'column',
        gap: '8px',
        background: 'var(--dsw-alias-bg-base)',
        color: 'var(--dsw-alias-label-primary)',
        fontSize: '12px',
      };

      if (state.phase === 'error') {
        return h('div', { style: root }, [
          h('div', { key: 'title', style: { color: 'var(--dsw-alias-label-primary)' } }, t('state.error')),
          h('div', { key: 'body', style: { color: 'var(--dsw-alias-label-tertiary)' } }, state.message),
        ]);
      }
      if (state.phase === 'loading') {
        return h('div', { style: root }, h('div', { style: { color: 'var(--dsw-alias-label-tertiary)' } }, t('state.loading')));
      }

      const data = state.data;
      if (data.exists !== true) {
        return h('div', { style: root }, [
          h('div', { key: 'frame', style: frame }, h('div', { style: { padding: '18px', textAlign: 'center', color: 'var(--dsw-alias-label-tertiary)' } }, [
            h('div', { key: 'title', style: { color: 'var(--dsw-alias-label-secondary)', marginBottom: '6px' } }, t('state.empty.title')),
            h('div', { key: 'body' }, t('state.empty.body')),
          ])),
          h(Caption, { key: 'dir', label: t('state.dir'), value: data.dir, title: data.dir }),
        ]);
      }

      const ageMs = Math.max(0, now - (data.mtimeMs ?? now));
      const fresh = ageMs < FRESH_MS;
      return h('div', { style: root }, [
        h('div', { key: 'head', style: { display: 'flex', alignItems: 'center', gap: '6px' } }, [
          h('span', {
            key: 'dot',
            style: {
              width: '7px',
              height: '7px',
              borderRadius: '50%',
              flex: 'none',
              background: fresh ? 'var(--dsw-alias-brand-primary)' : 'var(--dsw-alias-label-dimmed)',
            },
          }),
          h('span', { key: 'label', style: { color: fresh ? 'var(--dsw-alias-label-primary)' : 'var(--dsw-alias-label-tertiary)' } },
            `${fresh ? t('state.live') : t('state.stale')} · ${t('state.updated')}${Math.round(ageMs / 1000)}${t('ago')}`),
        ]),
        h('div', { key: 'frame', style: frame },
          h('img', {
            src: `${IMAGE_PATH}?v=${String(data.mtimeMs ?? 0)}`,
            alt: t('type.label'),
            style: { width: '100%', display: 'block' },
          })),
        h(Caption, { key: 'file', label: t('state.updated'), value: data.name ?? '', title: data.path ?? '' }),
        h(Caption, { key: 'dir', label: t('state.dir'), value: data.dir ?? '', title: data.dir ?? '' }),
      ]);
    }

    return {
      inject: ['slots', 'locale', 'sidebarRightTabs'],
      /**
       * Register the tab type, its copy, and its body seat; each registration is
       * owned by this plugin's lifetime through `ctx.effect`.
       * @param ctx - Client root context carrying the slot registry, copy, and the tab registry.
       */
      apply(ctx) {
        const t = ctx.locale.bind(NS);
        ctx.effect(() => ctx.locale.register(NS, { zh, en }), 'agent-browser-viewer: dictionaries');
        ctx.effect(() => ctx.sidebarRightTabs.register({
          id: ID,
          kind: KIND,
          title: () => t('type.label'),
          guide: [{
            id: 'live',
            order: 25,
            title: () => t('guide.title'),
            description: () => t('guide.description'),
          }],
        }), 'agent-browser-viewer: type');
        ctx.effect(() => ctx.slots.inject('sidebar.right.pane.tab', () => ctx.slots.register({
          name: 'sidebar.right.pane.tab',
          key: ID,
          locale: NS,
        }, Viewer)), 'agent-browser-viewer: body');
      },
    };
  },
});
